        except (ValueError, IndexError):
            return False
    actual = stat.S_IMODE(mode)
    if prefix == "-":
        return actual & wanted == wanted
    if prefix in ("/", "+"):
        return wanted == 0 or bool(actual & wanted)
    return actual == wanted


